189	  async invokeOperation<T = unknown>(
190	    operationId: string,
191	    input?: unknown,
192	    options?: AdminClientRequestOptions,
193	  ): Promise<AdminOperationResult<T>> {
194	    return this.request<AdminOperationResult<T>>(
