203	  private async request<T>(
204	    method: string,
205	    path: string,
206	    input?: unknown,
207	    options: AdminClientRequestOptions = {},
208	    unwrap = true,
209	  ): Promise<T> {
210	    const configured = typeof this.configuredHeaders === "function" ? await this.configuredHeaders() : this.configuredHeaders;
211	    const headers = new Headers(configured);
212	    new Headers(options.headers).forEach((value, key) => headers.set(key, value));
213	    headers.set("accept", "application/json");
214	    const idempotencyKey = options.idempotencyKey ?? this.defaults?.idempotencyKey;
215	    const confirmationToken = options.confirmationToken ?? this.defaults?.confirmationToken;
216	    if (idempotencyKey) headers.set("idempotency-key", idempotencyKey);
217	    if (confirmationToken) headers.set("x-admin-confirmation", confirmationToken);
218	    const isQuery = method === "GET" || method === "DELETE";
219	    if (!isQuery && input !== undefined) headers.set("content-type", "application/json");
220	    const response = await this.fetcher(joinUrl(this.baseUrl, `${path}${isQuery ? encodeQuery(input) : ""}`), {
221	      method,
222	      headers,
223	      signal: options.signal,
224	      ...(isQuery || input === undefined ? {} : { body: JSON.stringify(input) }),
225	    });
226	    const payload = await response.json().catch(() => undefined) as T | AdminResult | undefined;
227	    if (!response.ok) {
228	      const result = payload && typeof payload === "object" && "ok" in payload ? payload as AdminResult : undefined;
229	      throw new AdminClientError(result && result.ok === false ? result.error.message : `Administration request failed with HTTP ${response.status}.`, response.status, result);
