   105	      throw new McpError(ErrorCode.InvalidParams, "Expired McpFn pagination cursor");
   106	    }
   107	  }
   108	  const selected = values.slice(offset, offset + pageSize);
   109	  const nextOffset = offset + selected.length;
   110	  return {
   111	    values: selected,
   112	    ...(nextOffset < values.length ? { nextCursor: `mcpfn:${nextOffset}` } : {}),
   113	  };
