 921	    let entry: AdminRegistryOperation;
 922	    let immutable: { input: unknown; state: SuperConsoleRequestState };
 923	    try {
 924	      entry = this.registry.requireOperation(operationId);
 925	      if (!entry.operation.safety.requiresConfirmation) throw new SuperConsoleHttpError('This operation does not require a confirmation token.', { status: 400, code: 'CONFIRMATION_NOT_REQUIRED' });
 926	      const schema = entry.operation.inputSchema;
