 950	  private async performConfirmOperation(entry: AdminRegistryOperation, input: unknown, state: SuperConsoleRequestState) {
 951	    if (!this.options.confirmation) throw new SuperConsoleHttpError('Confirmation issuance is unavailable.', { status: 503, code: 'CONFIRMATION_UNAVAILABLE' });
 952	    const permission = entry.operation.permission;
 953	    this.requirePermission(state.principal, permission);
 954	    if (this.options.policy) {
 955	      const decision = await this.options.policy.authorize({ entry, input, context: state.context });
 956	      if (!decision.allowed) throw new SuperConsoleHttpError(decision.reason ?? 'The confirmation policy denied this operation.', { status: 403, code: 'CONFIRMATION_DENIED' });
 957	    }
 958	    const issued = await this.options.confirmation.issue({
 959	      operationId: entry.operation.id,
 960	      input,
 961	      principal: state.principal,
 962	      context: state.context,
 963	    });
 964	    if (!issued.token || Number.isNaN(new Date(issued.expiresAt).valueOf())) throw new SuperConsoleHttpError('The confirmation service returned an invalid token receipt.', { status: 503, code: 'CONFIRMATION_ISSUE_FAILED' });
