    88	      key,
    89	      (redactImplicitSecrets && isImplicitSecretKey(key)) || explicit.has(normalizeKey(key)) ? "[REDACTED]" : visit(item),
    90	    ]));
    91	    seen.delete(current);
    92	    return redacted;
    93	  };
