     2	import { stableSerialize } from "./validator.js";
     3	import type { AdminResult, AdminScope } from "./types.js";
     4	
     5	export interface AdminIdempotencyIdentity {
     6	  key: string;
     7	  actorId: string;
     8	  scope: AdminScope;
     9	  operationId: string;
    10	}
    11	
    12	export interface AdminIdempotencyRecord<T = unknown> {
    13	  identity: AdminIdempotencyIdentity;
    14	  fingerprint: string;
    15	  result: AdminResult<T>;
    16	  auditId?: string;
    17	  createdAt: string;
    18	}
    19	
    20	export interface AdminIdempotencyClaim {
    21	  identity: AdminIdempotencyIdentity;
    22	  fingerprint: string;
    23	  token: string;
    24	}
    25	
    26	export type AdminIdempotencyBeginResult<T = unknown> =
    27	  | { status: "acquired"; claim: AdminIdempotencyClaim }
    28	  | { status: "replay"; record: AdminIdempotencyRecord<T> }
    29	  | {
    30	      status: "in-progress";
    31	      /** In-process stores may provide completion notification. Distributed stores normally return retryAfterMs. */
    32	      wait?: Promise<AdminIdempotencyRecord<T> | undefined>;
    33	      retryAfterMs?: number;
    34	    };
    35	
    36	/**
    37	 * Atomic reservation contract. Durable implementations must make `begin` a
    38	 * compare-and-create operation on the full identity and must fence `complete`
    39	 * and `release` with the claim token. `release` is used only before domain
    40	 * invocation, so a failed audit/policy dependency cannot poison a safe retry.
    41	 * Cross-process stores should use a renewable lease or a documented stale-claim
    42	 * recovery policy.
    43	 */
    44	export interface AdminIdempotencyStore {
    45	  begin<T = unknown>(input: {
    46	    identity: AdminIdempotencyIdentity;
    47	    fingerprint: string;
    48	  }): Promise<AdminIdempotencyBeginResult<T>> | AdminIdempotencyBeginResult<T>;
    49	  complete<T = unknown>(
    50	    claim: AdminIdempotencyClaim,
    51	    record: AdminIdempotencyRecord<T>,
    52	  ): Promise<void> | void;
    53	  release(claim: AdminIdempotencyClaim): Promise<void> | void;
    54	}
    55	
    56	export function adminIdempotencyStorageKey(identity: AdminIdempotencyIdentity): string {
    57	  return stableSerialize(identity);
    58	}
    59	
    60	export async function adminInputFingerprint(input: unknown): Promise<string> {
    61	  const bytes = new TextEncoder().encode(stableSerialize(input));
    62	  const digest = await crypto.subtle.digest("SHA-256", bytes);
    63	  return `sha256:${Array.from(new Uint8Array(digest), (byte) =>
    64	    byte.toString(16).padStart(2, "0"),
    65	  ).join("")}`;
    66	}
    67	
    68	interface MemoryPendingEntry {
    69	  status: "in-progress";
    70	  fingerprint: string;
    71	  token: string;
    72	  wait: Promise<AdminIdempotencyRecord | undefined>;
    73	  resolve: (record: AdminIdempotencyRecord | undefined) => void;
    74	}
    75	
    76	interface MemoryCompletedEntry {
    77	  status: "completed";
    78	  fingerprint: string;
    79	  record: AdminIdempotencyRecord;
    80	}
    81	
    82	/** Process-local atomic test/development store. It is not durable or multi-process safe. */
    83	export class MemoryAdminIdempotencyStore implements AdminIdempotencyStore {
    84	  private readonly entries = new Map<string, MemoryPendingEntry | MemoryCompletedEntry>();
    85	
    86	  begin<T = unknown>(input: {
    87	    identity: AdminIdempotencyIdentity;
    88	    fingerprint: string;
    89	  }): AdminIdempotencyBeginResult<T> {
    90	    const key = adminIdempotencyStorageKey(input.identity);
    91	    const existing = this.entries.get(key);
    92	    if (existing && existing.fingerprint !== input.fingerprint) {
    93	      throw new AdminError("conflict", "The idempotency key was already used with different input.");
    94	    }
    95	    if (existing?.status === "completed") {
    96	      return { status: "replay", record: structuredClone(existing.record) as AdminIdempotencyRecord<T> };
    97	    }
    98	    if (existing?.status === "in-progress") {
    99	      return { status: "in-progress", wait: existing.wait as Promise<AdminIdempotencyRecord<T> | undefined> };
   100	    }
   101	
   102	    let resolve!: (record: AdminIdempotencyRecord | undefined) => void;
   103	    const wait = new Promise<AdminIdempotencyRecord | undefined>((complete) => { resolve = complete; });
   104	    const token = `claim_${crypto.randomUUID()}`;
   105	    this.entries.set(key, { status: "in-progress", fingerprint: input.fingerprint, token, wait, resolve });
   106	    return { status: "acquired", claim: { identity: input.identity, fingerprint: input.fingerprint, token } };
   107	  }
   108	
   109	  complete<T = unknown>(claim: AdminIdempotencyClaim, record: AdminIdempotencyRecord<T>): void {
   110	    const key = adminIdempotencyStorageKey(claim.identity);
   111	    const existing = this.entries.get(key);
   112	    if (!existing || existing.status !== "in-progress" || existing.token !== claim.token) {
   113	      throw new AdminError("conflict", "The idempotency reservation is no longer owned by this operation.");
   114	    }
   115	    if (existing.fingerprint !== claim.fingerprint || record.fingerprint !== claim.fingerprint) {
   116	      throw new AdminError("conflict", "The idempotency completion fingerprint does not match its reservation.");
   117	    }
   118	    const snapshot = structuredClone(record) as AdminIdempotencyRecord;
   119	    this.entries.set(key, { status: "completed", fingerprint: claim.fingerprint, record: snapshot });
   120	    existing.resolve(structuredClone(snapshot));
   121	  }
   122	
   123	  release(claim: AdminIdempotencyClaim): void {
   124	    const key = adminIdempotencyStorageKey(claim.identity);
   125	    const existing = this.entries.get(key);
   126	    if (!existing || existing.status !== "in-progress" || existing.token !== claim.token) {
   127	      throw new AdminError("conflict", "The idempotency reservation is no longer owned by this operation.");
   128	    }
   129	    if (existing.fingerprint !== claim.fingerprint) {
   130	      throw new AdminError("conflict", "The idempotency release fingerprint does not match its reservation.");
   131	    }
   132	    this.entries.delete(key);
   133	    existing.resolve(undefined);
   134	  }
   135	}
   136	
   137	export async function beginAdminIdempotency<T>(
   138	  store: AdminIdempotencyStore,
   139	  identity: AdminIdempotencyIdentity,
   140	  input: unknown,
   141	): Promise<
   142	  | { status: "acquired"; claim: AdminIdempotencyClaim }
   143	  | { status: "replay"; record: AdminIdempotencyRecord<T> }
   144	> {
   145	  const fingerprint = await adminInputFingerprint(input);
   146	  // A released in-process claim may resolve without a record; retry its atomic begin once observed.
   147	  for (;;) {
   148	    const reservation = await store.begin<T>({ identity, fingerprint });
   149	    if (reservation.status === "acquired" || reservation.status === "replay") return reservation;
   150	    if (!reservation.wait) {
   151	      throw new AdminError("conflict", "An operation with this idempotency key is already in progress.", {
   152	        details: { retryAfterMs: reservation.retryAfterMs },
   153	        retryable: true,
   154	      });
   155	    }
   156	    const record = await reservation.wait;
   157	    if (record) return { status: "replay", record };
   158	  }
   159	}
