   471	  private defaultPolicy(entry: AdminRegistryOperation, context: AdminOperationContext): AdminPolicyDecision {
   472	    const permissions = context.actor.permissions ?? [];
   473	    return { allowed: permissions.includes("*") || permissions.includes(entry.operation.permission) };
