   476	  private idempotencyIdentity(entry: AdminRegistryOperation, context: AdminOperationContext): AdminIdempotencyIdentity | undefined {
   477	    if (entry.operation.safety.classification === "read" || !context.idempotencyKey || !entry.operation.safety.idempotent) return undefined;
   478	    return { key: context.idempotencyKey, actorId: context.actor.id, scope: context.scope, operationId: entry.operation.id };
