176	      );
177	      const permissionDecision = this.defaultPolicy(entry, request.context);
178	      if (!permissionDecision.allowed) {
179	        throw new AdminError("forbidden", "The active actor cannot perform this operation.");
180	      }
181	      const decision = this.policy
182	        ? await this.policy.authorize({ entry, input: request.input, context: request.context })
183	        : permissionDecision;
184	      policyMetadata = decision.metadata;
185	      if (!decision.allowed) throw new AdminError("forbidden", decision.reason || "The active actor cannot perform this operation.");
186	
187	      if (entry.operation.safety.requiresConfirmation) {
188	        const token = request.context.confirmationToken;
189	        if (!token) throw new AdminError("precondition_failed", "This operation requires explicit confirmation.");
190	        if (!this.confirmation) {
191	          throw new AdminError("dependency_unavailable", "Administration confirmation verification is unavailable.");
192	        }
193	        if (!(await this.confirmation.verify({ entry, input: request.input, context: request.context, token }))) {
194	          throw new AdminError("precondition_failed", "The operation confirmation is invalid or expired.");
195	        }
196	      }
197	
198	      if (entry.operation.safety.audit === "required" && !this.audit) {
199	        throw new AdminError("dependency_unavailable", "A required administration audit sink is unavailable.");
200	      }
201	
202	      const identity = this.idempotencyIdentity(entry, request.context);
203	      if (entry.operation.safety.classification !== "read" && entry.operation.safety.idempotent && !identity) {
204	        throw new AdminError("precondition_failed", "This operation requires an idempotency key.");
205	      }
206	      if (identity && !this.idempotency) {
207	        throw new AdminError("dependency_unavailable", "Durable administration idempotency storage is unavailable.");
208	      }
209	      if (identity && this.idempotency) {
210	        const reservation = await beginAdminIdempotency<T>(this.idempotency, identity, request.input);
211	        if (reservation.status === "replay") {
