213	          const originalAuditId = reservation.record.auditId ?? prior.auditId;
214	          const recoveringAudit = reservation.record.audit?.status === "pending";
215	          let replayAuditId: string | undefined;
216	          if (this.shouldAudit(entry)) {
217	            terminalAuditAttempted = true;
218	            const candidateAuditId = this.createAuditId();
