 42	/**
 43	 * Atomic reservation contract. Durable implementations must make `begin` a
 44	 * compare-and-create operation on the full identity and must fence `complete`
 45	 * and `release` with the claim token. `release` is used only before domain
 46	 * invocation, so a failed audit/policy dependency cannot poison a safe retry.
 47	 * Cross-process stores should use a renewable lease or a documented stale-claim
 48	 * recovery policy. `complete` must be safely repeatable with the same claim,
 49	 * identity, fingerprint and result: the dispatcher retries it after ambiguous
 50	 * dependency acknowledgement failures and never re-invokes the domain.
 51	 */
 52	export interface AdminIdempotencyStore {
 53	  begin<T = unknown>(input: {
 54	    identity: AdminIdempotencyIdentity;
 55	    fingerprint: string;
 56	  }): Promise<AdminIdempotencyBeginResult<T>> | AdminIdempotencyBeginResult<T>;
 57	  complete<T = unknown>(
 58	    claim: AdminIdempotencyClaim,
 59	    record: AdminIdempotencyRecord<T>,
 60	  ): Promise<void> | void;
 61	  /**
 62	   * Optional reconciliation hook. Implementations atomically update only a
 63	   * completed record with the same identity and fingerprint. It lets a replay
 64	   * close a terminal-audit gap without re-running the domain mutation.
 65	   */
 66	  finalizeAudit?(
 67	    identity: AdminIdempotencyIdentity,
 68	    fingerprint: string,
 69	    input: { auditId: string; completedAt: string },
 70	  ): Promise<void> | void;
 71	  release(claim: AdminIdempotencyClaim): Promise<void> | void;
 72	}
