 78	export async function adminInputFingerprint(input: unknown): Promise<string> {
 79	  const bytes = new TextEncoder().encode(stableSerialize(input));
 80	  const digest = await crypto.subtle.digest("SHA-256", bytes);
 81	  return `sha256:${Array.from(new Uint8Array(digest), (byte) =>
 82	    byte.toString(16).padStart(2, "0"),
 83	  ).join("")}`;
 84	}
