 87	  status: "in-progress";
 88	  fingerprint: string;
 89	  token: string;
 90	  wait: Promise<AdminIdempotencyRecord | undefined>;
 91	  resolve: (record: AdminIdempotencyRecord | undefined) => void;
 92	}
