101	/** Process-local atomic test/development store. It is not durable or multi-process safe. */
102	export class MemoryAdminIdempotencyStore implements AdminIdempotencyStore {
103	  private readonly entries = new Map<string, MemoryPendingEntry | MemoryCompletedEntry>();
104	
105	  begin<T = unknown>(input: {
106	    identity: AdminIdempotencyIdentity;
107	    fingerprint: string;
108	  }): AdminIdempotencyBeginResult<T> {
109	    const key = adminIdempotencyStorageKey(input.identity);
110	    const existing = this.entries.get(key);
111	    if (existing && existing.fingerprint !== input.fingerprint) {
112	      throw new AdminError("conflict", "The idempotency key was already used with different input.");
113	    }
114	    if (existing?.status === "completed") {
115	      return { status: "replay", record: structuredClone(existing.record) as AdminIdempotencyRecord<T> };
116	    }
117	    if (existing?.status === "in-progress") {
118	      return { status: "in-progress", wait: existing.wait as Promise<AdminIdempotencyRecord<T> | undefined> };
119	    }
120	
121	    let resolve!: (record: AdminIdempotencyRecord | undefined) => void;
122	    const wait = new Promise<AdminIdempotencyRecord | undefined>((complete) => { resolve = complete; });
123	    const token = `claim_${crypto.randomUUID()}`;
124	    this.entries.set(key, { status: "in-progress", fingerprint: input.fingerprint, token, wait, resolve });
125	    return { status: "acquired", claim: { identity: input.identity, fingerprint: input.fingerprint, token } };
126	  }
127	
128	  complete<T = unknown>(claim: AdminIdempotencyClaim, record: AdminIdempotencyRecord<T>): void {
129	    const key = adminIdempotencyStorageKey(claim.identity);
130	    const existing = this.entries.get(key);
131	    if (existing?.status === "completed" && existing.token === claim.token) {
132	      if (existing.fingerprint !== claim.fingerprint || record.fingerprint !== claim.fingerprint) {
133	        throw new AdminError("conflict", "The idempotency completion fingerprint does not match its reservation.");
134	      }
135	      existing.record = structuredClone(record) as AdminIdempotencyRecord;
136	      return;
137	    }
138	    if (!existing || existing.status !== "in-progress" || existing.token !== claim.token) {
139	      throw new AdminError("conflict", "The idempotency reservation is no longer owned by this operation.");
140	    }
141	    if (existing.fingerprint !== claim.fingerprint || record.fingerprint !== claim.fingerprint) {
142	      throw new AdminError("conflict", "The idempotency completion fingerprint does not match its reservation.");
143	    }
144	    const snapshot = structuredClone(record) as AdminIdempotencyRecord;
145	    this.entries.set(key, { status: "completed", fingerprint: claim.fingerprint, token: claim.token, record: snapshot });
146	    existing.resolve(structuredClone(snapshot));
147	  }
148	
149	  finalizeAudit(
150	    identity: AdminIdempotencyIdentity,
151	    fingerprint: string,
152	    input: { auditId: string; completedAt: string },
153	  ): void {
154	    const existing = this.entries.get(adminIdempotencyStorageKey(identity));
155	    if (!existing || existing.status !== "completed" || existing.fingerprint !== fingerprint) {
156	      throw new AdminError("conflict", "The idempotency record is unavailable for audit reconciliation.");
157	    }
158	    existing.record = {
159	      ...existing.record,
160	      auditId: input.auditId,
161	      result: { ...existing.record.result, auditId: input.auditId },
162	      audit: { status: "completed", auditId: input.auditId, updatedAt: input.completedAt },
163	    };
164	  }
165	
166	  release(claim: AdminIdempotencyClaim): void {
167	    const key = adminIdempotencyStorageKey(claim.identity);
168	    const existing = this.entries.get(key);
169	    if (!existing || existing.status !== "in-progress" || existing.token !== claim.token) {
170	      throw new AdminError("conflict", "The idempotency reservation is no longer owned by this operation.");
171	    }
172	    if (existing.fingerprint !== claim.fingerprint) {
173	      throw new AdminError("conflict", "The idempotency release fingerprint does not match its reservation.");
174	    }
175	    this.entries.delete(key);
176	    existing.resolve(undefined);
177	  }
178	}
