180	export async function beginAdminIdempotency<T>(
181	  store: AdminIdempotencyStore,
182	  identity: AdminIdempotencyIdentity,
183	  input: unknown,
184	): Promise<
185	  | { status: "acquired"; claim: AdminIdempotencyClaim }
186	  | { status: "replay"; record: AdminIdempotencyRecord<T> }
187	> {
188	  const fingerprint = await adminInputFingerprint(input);
189	  // A released in-process claim may resolve without a record; retry its atomic begin once observed.
190	  for (;;) {
191	    const reservation = await store.begin<T>({ identity, fingerprint });
192	    if (reservation.status === "acquired" || reservation.status === "replay") return reservation;
193	    if (!reservation.wait) {
194	      throw new AdminError("conflict", "An operation with this idempotency key is already in progress.", {
195	        details: { retryAfterMs: reservation.retryAfterMs },
196	        retryable: true,
197	      });
198	    }
199	    const record = await reservation.wait;
200	    if (record) return { status: "replay", record };
201	  }
