   973	      entry = this.registry.requireOperation(operationId);
   974	      if (!(await this.operationDiscoverable(entry, state))) {
   975	        throw new AdminError('not_found', 'The requested confirmation operation is unavailable.');
   976	      }
   977	      if (!entry.operation.safety.requiresConfirmation) throw new SuperConsoleHttpError('This operation does not require a confirmation token.', { status: 400, code: 'CONFIRMATION_NOT_REQUIRED' });
   978	      const schema = entry.operation.inputSchema;
