   987	      await this.auditConfirmation(entry, operationId, immutable.input, immutable.state.context, 'attempted', started);
   988	    } catch {
   989	      throw new SuperConsoleHttpError('The confirmation attempt could not be audited.', { status: 503, code: 'AUDIT_UNAVAILABLE', details: { retryable: true } });
   990	    }
   991	    let receipt: { token: string; expiresAt: string };
   992	    try {
   993	      receipt = await this.performConfirmOperation(entry, immutable.input, immutable.state);
   994	    } catch (error) {
   995	      await this.auditConfirmation(entry, operationId, immutable.input, immutable.state.context, 'denied', started, normalizeAdminError(error).error.code);
   996	      throw error;
   997	    }
