   282	function cursorFromResult(result: AdminOperationResult<unknown>, outputPath = "nextCursor"): string | null {
   283	  if (result.page?.nextCursor !== undefined) return result.page.nextCursor ?? null;
   284	  let value: unknown = result.data;
   285	  for (const segment of outputPath.split(".").filter(Boolean)) {
   286	    if (!value || typeof value !== "object" || Array.isArray(value)) return null;
   287	    value = (value as Record<string, unknown>)[segment];
   288	  }
   289	  return typeof value === "string" && value.length > 0 ? value : null;
   290	}
