  content?: string;
  // Cycle name, number, or ID. When passing a name or number, also pass `team` to disambiguate.
  cycle?: string;
  // Icon name or emoji code (e.g. "Rocket" or ":eagle:"), not a raw Unicode emoji
  icon?: string;
